    fn proxy_storage(tag: u8) -> (TestVM, UUPSProxyErc20Example) {
        let vm = TestVMBuilder::new()
            .contract_address(Address::repeat_byte(tag))
            .build();
        let contract = UUPSProxyErc20Example::from(&vm);
