async fn upgrade_through_valid_proxy_succeeds() -> Result<()> {
    let alice = Account::new().await?;
    let bob = Account::new().await?;

    let logic_addr = alice.deploy_uups().await?.contract_address;

    let proxy_addr =
        alice.deploy_proxy(logic_addr, alice.address()).await?.contract_address;

    let logic = UUPSProxyErc20Example::new(logic_addr, &alice.wallet);
    let proxy = Erc1967Example::new(proxy_addr, &alice.wallet);

    // assert proxy and logic initialized correctly
    assert_eq!(logic_addr, proxy.implementation().call().await?);
    assert_eq!(
        UPGRADE_INTERFACE_VERSION,
        proxy.UPGRADE_INTERFACE_VERSION().call().await?,
    );
    assert_eq!(
        UPGRADE_INTERFACE_VERSION,
        logic.UPGRADE_INTERFACE_VERSION().call().await?,
    );
    assert_eq!(
        uups_upgradeable::VERSION_NUMBER,
        U32::from(proxy.getVersion().call().await?),
    );
    assert_eq!(
        uups_upgradeable::VERSION_NUMBER,
        U32::from(logic.getVersion().call().await?),
    );
    // check that state is set correctly
    assert_eq!(alice.address(), proxy.owner().call().await?);

    let attacker_proxy = Erc1967Example::new(proxy_addr, &bob.wallet);
    let err = send!(attacker_proxy.initialize(bob.address()))
        .expect_err("v1 initializer must not transfer ownership");
    assert!(err.reverted_with(UUPSProxyErc20Example::InvalidInitialization {}));
    assert_eq!(alice.address(), proxy.owner().call().await?);

    // deploy the new UUPS contract
    let new_logic_addr =
        alice.deploy_uups_new_version().await?.contract_address;
    let new_logic = UUPSProxyErc20Example::new(new_logic_addr, &alice.wallet);

    // no need to reinitialize the proxy state when upgrading, as old state
    // should be maintained
    let receipt =
        receipt!(proxy.upgradeToAndCall(new_logic_addr, vec![].into()))?;

    assert!(receipt
        .emits(Erc1967Example::Upgraded { implementation: new_logic_addr }));

    assert_eq!(new_logic_addr, proxy.implementation().call().await?);
    assert_eq!(
        UPGRADE_INTERFACE_VERSION,
        proxy.UPGRADE_INTERFACE_VERSION().call().await?,
    );
    assert_eq!(
        uups_proxy_new_version_example::VERSION_NUMBER,
        U32::from(proxy.getVersion().call().await?),
    );
    assert_eq!(
        uups_proxy_new_version_example::VERSION_NUMBER,
        U32::from(new_logic.getVersion().call().await?),
    );

    // Alice should still be the owner
    assert_eq!(alice.address(), proxy.owner().call().await?);

    let attacker_proxy = Erc1967Example::new(proxy_addr, &bob.wallet);
    let err = send!(attacker_proxy.initialize(bob.address()))
        .expect_err("v2 initializer must not transfer ownership");
    assert!(err.reverted_with(UUPSProxyErc20Example::InvalidInitialization {}));
    assert_eq!(alice.address(), proxy.owner().call().await?);

    Ok(())
}

