                to,
                alloy_primitives::U128::from(batch_size),
            );

            self.vm().log(ConsecutiveTransfer {
                from_token_id: next.to::<U256>(),
                to_token_id: last.to::<U256>(),
                from_address: Address::ZERO,
                to_address: to,
            });
