    };
    ($first:expr $(, $rest:expr)* $(,)?) => {{
        use $crate::devnet_test_support::AbiTypeToString as _;
        let first = $first;
        #[allow(unused_mut)]
        let mut args = vec![first.abi_type_to_string()];
        $(
            let arg = $rest;
            args.push(arg.abi_type_to_string());
