    /// * `&self` - Read access to the contract's state.
    fn _next_consecutive_id(&self) -> U96 {
        match self.sequential_ownership.latest_checkpoint() {
            None => self._first_consecutive_id(),
            Some((latest_id, _)) => latest_id + uint!(1_U96),
        }
    }

