    fn supports_interface(&self, interface_id: B32) -> bool {
        self.erc721.supports_interface(interface_id)
    }
}

use stylus_sdk::prelude::errors::MethodError;
#[cfg(test)]
mod tests {
    use crate::test_support::{
        mock_code, test_address, TestContract as TestVMContract,
    };
    use alloy_primitives::{uint, Address, U256};

    use super::*;

    const FIRST_CONSECUTIVE_TOKEN_ID: U96 = uint!(0_U96);
    const MAX_BATCH_SIZE: U96 = uint!(5000_U96);
    const TOKEN_ID: U256 = uint!(1_U256);
    const NON_CONSECUTIVE_TOKEN_ID: U256 = uint!(10001_U256);

    fn deployed_contract() -> TestVMContract<Erc721Consecutive> {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        mock_code(contract.vm(), contract.address());
        contract
    }

    impl Erc721Consecutive {
        fn init(&mut self, receivers: Vec<Address>, batches: Vec<U96>) {
            self.first_consecutive_id.set(FIRST_CONSECUTIVE_TOKEN_ID);
            self.max_batch_size.set(MAX_BATCH_SIZE);
            for (to, batch_size) in receivers.into_iter().zip(batches) {
                self._mint_consecutive(to, batch_size)
                    .expect("should mint consecutively");
            }
        }
    }

    #[test]
    fn mints() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let initial_balance = contract
            .sender(alice)
            .balance_of(alice)
            .expect("should return the balance of Alice");

        let init_tokens_count = uint!(10_U96);
        contract.sender(alice).init(vec![alice], vec![init_tokens_count]);
        mock_code(contract.vm(), contract.address());

        let balance1 = contract
            .sender(alice)
            .balance_of(alice)
            .expect("should return the balance of Alice");
        assert_eq!(balance1, initial_balance + U256::from(init_tokens_count));

        // Check non-consecutive mint.
        let non_consecutive_token_id = uint!(10_U256);
        contract
            .sender(alice)
            ._mint(alice, non_consecutive_token_id)
            .expect("should mint a token for Alice");
        let owner = contract
            .sender(alice)
            .owner_of(non_consecutive_token_id)
            .expect("should return the owner of the token");
        assert_eq!(owner, alice);

        let balance2 = contract
            .sender(alice)
            .balance_of(alice)
            .expect("should return the balance of Alice");

        assert_eq!(balance2, balance1 + uint!(1_U256));
    }

    #[test]
    fn individual_mint_is_forbidden_during_constructor() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let error = contract.sender(alice)._mint(alice, TOKEN_ID).expect_err(
            "individual mint must be unavailable during construction",
        );


        assert!(matches!(error, Error::ForbiddenMint(_)));
        assert_eq!(
            U256::ZERO,
            contract.sender(alice).balance_of(alice).expect("balance query"),
        );
    }

    #[test]
    fn error_when_minting_token_id_twice() {
        let contract = deployed_contract();
        let alice = test_address(stringify!(alice));

        contract
            .sender(alice)
            ._mint(alice, TOKEN_ID)
            .expect("should mint the token a first time");
        let err = contract
            .sender(alice)
            ._mint(alice, TOKEN_ID)
            .expect_err("should not mint a token with `TOKEN_ID` twice");

        assert!(matches!(
            err,
            Error::InvalidSender(ERC721InvalidSender { sender: Address::ZERO })
        ));
    }

    #[test]
    fn error_when_minting_token_invalid_receiver() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let invalid_receiver = Address::ZERO;

        let err = contract
            .sender(alice)
            ._mint(invalid_receiver, TOKEN_ID)
            .expect_err("should not mint a token for invalid receiver");

        assert!(matches!(
            err,
            Error::InvalidReceiver(ERC721InvalidReceiver {
                receiver
            }) if receiver == invalid_receiver
        ));
    }

    #[test]
    fn error_when_to_is_zero() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let err = contract
            .sender(alice)
            ._mint_consecutive(Address::ZERO, uint!(11_U96))
            .expect_err("should not mint consecutive");
        assert!(matches!(
            err,
            Error::InvalidReceiver(ERC721InvalidReceiver {
                receiver: Address::ZERO
            })
        ));
    }

    #[test]
    fn error_when_exceed_batch_size() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let batch_size =
            contract.sender(alice)._max_batch_size() + uint!(1_U96);
        let err = contract
            .sender(alice)
            ._mint_consecutive(alice, batch_size)
            .expect_err("should not mint consecutive");
        assert!(matches!(
            err,
            Error::ExceededMaxBatchMint(ERC721ExceededMaxBatchMint {
                batch_size,
                max_batch
            })
            if batch_size == U256::from(batch_size) && max_batch == U256::from(contract.sender(alice)._max_batch_size())
        ));
    }

    #[test]
    fn transfers_from() {
        let contract =
            TestVMContract::<Erc721Consecutive>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        // Mint batches of 1000 tokens to Alice and Bob.
        contract
            .sender(alice)
            .init(vec![alice, bob], vec![uint!(1000_U96), uint!(1000_U96)]);
        mock_code(contract.vm(), contract.address());

        // Transfer first consecutive token from Alice to Bob.
        contract
            .sender(alice)
            .transfer_from(alice, bob, U256::from(FIRST_CONSECUTIVE_TOKEN_ID))
            .expect("should transfer a token from Alice to Bob");

        let owner = contract
            .sender(alice)
            .owner_of(U256::from(FIRST_CONSECUTIVE_TOKEN_ID))

